   670→    # Loop depth tracking methods
   671→    method begin_loop_tracking() {
   672→        # Increment loop depth when entering a loop
   673→        $loop_depth++;
   674→        # Push a new set to track modified variables at this loop depth
   675→        push $loop_modified_vars->@*, {};
   676→        return;
   677→    }
   678→
   679→    method end_loop_tracking() {
   680→        # Decrement loop depth when exiting a loop
   681→        if ($loop_depth > 0) {
   682→            $loop_depth--;
   683→            # Pop the modified variables set for this loop
   684→            pop $loop_modified_vars->@* if scalar($loop_modified_vars->@*) > 0;
   685→        }
   686→        return;
   687→    }
   688→
   689→    method is_tracking_loop() {
   690→        return $loop_depth > 0;
   691→    }
