   696→
   697→    method generate_loop_phi_nodes($loop_node) {
   698→        # Generate phi nodes for variables modified within the loop
   699→        # With context+labels approach, phi nodes are created for variables
   700→        # that exist both as 'lexical:$var' (pre-loop) and 'lexical:loop_N:$var' (in-loop)
   701→
   702→        my %phi_nodes;
   703→
   704→        # If we're not tracking a loop or have no modified vars, return empty
   705→        return \%phi_nodes unless scalar($loop_modified_vars->@*) > 0;
   706→
   707→        # Get the current loop's modified variables
   708→        my $modified_vars = $loop_modified_vars->[-1];
   709→
   710→        # For each modified variable, create a phi node
   711→        for my $var_name (keys($modified_vars->%*)) {
   712→            # Get pre-loop value (lexical:$var)
   713→            my $pre_loop_label = "lexical:$var_name";
   714→            my $pre_loop_value = $context->($pre_loop_label);
   715→
   716→            # Get loop-modified value (lexical:loop_N:$var where N = current depth - 1)
   717→            my $loop_label = "lexical:loop_" . ($loop_depth - 1) . ":$var_name";
   718→            my $loop_value = $context->($loop_label);
   719→
   720→            # Only create phi if both values exist
   721→            if (defined($pre_loop_value) && defined($loop_value)) {
   722→                # Build phi node with: control (loop), initial value, loop value
   723→                my $phi = $self->build_loop_phi_node(
   724→                    $loop_node,
   725→                    (ref($pre_loop_value) ? $pre_loop_value->id : $pre_loop_value),
   726→                    (ref($loop_value) ? $loop_value->id : $loop_value)
   727→                );
   728→                $phi_nodes{$var_name} = $phi;
   729→            }
   730→        }
   731→
   732→        return \%phi_nodes;
   733→    }
