  1210→    # Create reference to a scalar variable: \$x
  1211→    method build_scalar_ref_node($var_name) {
  1212→        my $label = "lexical:$var_name";
  1213→        # Look up the target node (might be object or ID)
  1214→        my $target_node_or_id = $context->($label);
  1215→        die "Cannot create reference to undefined variable $var_name" unless defined($target_node_or_id);
  1216→
  1217→        # Get the node ID for the dependency
  1218→        my $target_node_id = ref($target_node_or_id) ? $target_node_or_id->id : $target_node_or_id;
  1219→
  1220→        my $node_id = $self->next_node_id();
  1221→        my $reference = Chalk::IR::Node::Reference->new(
