  1247→        } else {
  1248→            $collection_node = $graph->get_node($collection_node_or_id);
  1249→        }
  1250→
  1251→        # Get the array context from the collection node
  1252→        my $array_ctx = $collection_node->array_context;
  1253→
  1254→        # Get the index value - need to evaluate it
  1255→        # For now, assume it's a constant node
  1256→        my $index_val = $index_node->value;
  1257→
  1258→        # Create the reference pointing to the array context with index: label
  1259→        my $label = Chalk::IR::Context->make_index_label($index_val);
  1260→        my $node_id = $self->next_node_id();
  1261→        my $reference = Chalk::IR::Node::Reference->new(
  1262→            id             => $node_id,
  1263→            inputs         => [$current_control, $collection_node->id, $index_node->id],
  1264→            target_context => $array_ctx,
  1265→            target_label   => $label,
  1266→        );
  1267→        $graph->add_node($reference);
  1268→
