  1271→            context => "collection=$collection_name, index_id=" . $index_node->id . ", index_val=$index_val"
  1272→        );
  1273→
  1274→        return $reference;
  1275→    }
  1276→
  1277→    # Dereference a scalar reference: $$ref
  1278→    method build_scalar_deref_node($ref_var_name) {
  1279→        # Get the reference from context (might be object or ID)
  1280→        my $ref_label = "lexical:$ref_var_name";
  1281→        my $ref_node_or_id = $context->($ref_label);
  1282→
  1283→        # Get the node ID
  1284→        my $ref_id = ref($ref_node_or_id) ? $ref_node_or_id->id : $ref_node_or_id;
  1285→
  1286→        # Create ScalarDeref node
  1287→        my $node_id = $self->next_node_id();
  1288→        my $deref = Chalk::IR::Node::ScalarDeref->new(
  1289→            id      => $node_id,
