  1321→
  1322→    # Assign through a dereferenced reference: $$ref = value
  1323→    method build_scalar_deref_assign_node($ref_var_name, $value_node) {
  1324→        # Get the reference from context
  1325→        my $ref_label = "lexical:$ref_var_name";
  1326→        my $ref_node_or_id = $context->($ref_label);
  1327→
  1328→        # Might be node object or node ID depending on when it was stored
  1329→        my $ref_node;
  1330→        if (ref($ref_node_or_id)) {
  1331→            $ref_node = $ref_node_or_id;
  1332→        } else {
  1333→            $ref_node = $graph->get_node($ref_node_or_id);
  1334→        }
  1335→
  1336→        # Get the target label from the reference
  1337→        my $target_label = $ref_node->target_label;
  1338→
  1339→        # Extend the BUILDER's current context with the new value (node object, not ID)
  1340→        # This updates the variable that the reference points to
  1341→        $context = Chalk::IR::Context->extend_context(
  1342→            $context,
  1343→            $target_label,
  1344→            $value_node
  1345→        );
  1346→
