     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→# Preload all polymorphic node classes for from_hash() factory
     8→use Chalk::IR::Node::Start;
     9→use Chalk::IR::Node::Constant;
