    36→class Chalk::IR::Node {
    37→    field $id             :param :reader;
    38→    field $op             :param :reader;
    39→    field $inputs         :param :reader;
    40→    field $attributes     :param :reader;
    41→    field $source_info    :param :reader = undef;
    42→    field $transform_chain :param :reader = undef;
    43→
    44→    method to_hash() {
    45→        return {
    46→            id              => $id,
    47→            op              => $op,
    48→            inputs          => $inputs,
    49→            attributes      => $attributes,
    50→            source_info     => $source_info,
    51→            transform_chain => $transform_chain,
    52→        };
    53→    }
    54→
    55→    # Get formatted source location string for error messages
    56→    method source_location() {
    57→        return $source_info ? $source_info->to_string() : undef;
    58→    }
    59→
    60→    # Record a transformation and return a new node with updated chain
    61→    method record_transform(%args) {
    62→        my $operation   = $args{operation}   // die "operation required";
    63→        my $rule_name   = $args{rule_name}   // undef;
    64→        my $description = $args{description} // undef;
    65→
    66→        # Create transform record
    67→        my $transform = {
    68→            operation      => $operation,
    69→            rule_name      => $rule_name,
    70→            description    => $description,
    71→            timestamp      => time(),
    72→            source_node_id => $id,
    73→        };
    74→
    75→        # Build new chain: copy existing + new transform
    76→        my $new_chain = $transform_chain ? [$transform_chain->@*] : [];
    77→        push $new_chain->@*, $transform;
    78→
    79→        # Return new node with updated chain (immutable pattern)
    80→        return ref($self)->new(
    81→            id              => $id,
    82→            op              => $op,
    83→            inputs          => $inputs,
    84→            attributes      => $attributes,
    85→            source_info     => $source_info,
    86→            transform_chain => $new_chain,
    87→        );
    88→    }
    89→
    90→    # Get formatted transformation history for debugging
    91→    method transform_history() {
    92→        return undef unless $transform_chain && $transform_chain->@*;
    93→
    94→        my @lines;
    95→        for my $transform ($transform_chain->@*) {
    96→            my $line = sprintf(
    97→                "%s: %s",
    98→                $transform->{operation},
    99→                $transform->{rule_name} // 'unknown'
   100→            );
   101→            if ($transform->{description}) {
   102→                $line .= " - $transform->{description}";
   103→            }
   104→            push @lines, $line;
   105→        }
   106→
   107→        return join("\n", @lines);
   108→    }
