   110→    # Factory method: create polymorphic node from hash representation
   111→    # Used by GVN to reconstruct nodes while preserving polymorphic types
   112→    sub from_hash($class, $hash) {
   113→        my $op = $hash->{op};
   114→        my $id = $hash->{id};
   115→        my $inputs = $hash->{inputs};
